/// Table size for the exponential family: `2`<sup>`q`</sup>` · 2`<sup>`j/N`</sup>` · exp(r)`
const EXP_N: i64 = 128;

/// The mantissa `2`<sup>`j/N`</sup>` · exp(r)` of the exponential family, as a
/// double-double normalized into [1, 2), with `q` adjusted for that normalization.
///
/// `r` is the reduced argument, `|r| ≤ ln2/2N`.  The full value is `2`<sup>`q`</sup>
/// times the returned mantissa.
#[inline]
pub(super) fn exp_mantissa(j: usize, q: i64, r: DoubleDouble) -> (DoubleDouble, i64) {
    // exp(r) by double-double Horner over the degree-8 minimax polynomial.
    let (high, low) = EXP_R_COEFFS[EXP_R_COEFFS.len() - 1];
    let mut acc = DoubleDouble { high, low };

    for &(high, low) in EXP_R_COEFFS[..EXP_R_COEFFS.len() - 1].iter().rev() {
        acc = acc * r + DoubleDouble { high, low };
    }

    // Fold the table entry in and normalize the mantissa.
    let (high, low) = EXP2_TABLE[j];
    let scaled = DoubleDouble { high, low } * acc;
    let product = fast_sum(scaled.high, scaled.low);

    // `2^(j/N) · exp(r)` lies in [0.997, 2.005); fold its exponent into `q` so the
    // mantissa is in [1, 2).
    if product.high < 1.0 {
        (product * 2.0, q - 1)
    } else if product.high >= 2.0 {
        (product * 0.5, q + 1)
    } else {
        (product, q)
    }
}

/// Fast double-double mantissa for the exponential family.
///
/// Same contract as [`exp_mantissa`] — returns `2`<sup>`j/N`</sup>` · exp(r)`
/// normalized into [1, 2) with `q` adjusted — but evaluates `exp(r)` with a
/// plain-`f64` tail polynomial instead of a double-double Horner.  This trades
/// the accurate path's ≈2⁻¹⁰⁰ for ≈2⁻⁶⁸ relative error at a fraction of the cost;
/// the callers' Ziv tests resolve the rare hard-to-round cases against an accurate
/// path.
#[inline]
pub(super) fn exp_mantissa_fast(j: usize, q: i64, r: DoubleDouble) -> (DoubleDouble, i64) {
    // The full reduced argument as one `f64`, for the small tail term.  `exp2`
    // and `exp10` hand in an *un-normalized* `r` (the `ln2/N` low word lands in
    // `r.low ≈ 2⁻⁴⁷`), so dropping `r.low` here would lose the `2·r.high·r.low`
    // part of `r²` — a ≈2⁻⁵⁵ slip the Ziv gate could not catch.
    let z = r.high + r.low;

    // exp(r) − 1 − r ≈ z²·P(z), with P evaluated in plain f64: it only forms a
    // term ≲2⁻¹⁷ of exp(r), so its `f64` rounding lands near 2⁻⁶⁸ relative.
    let tail = (z * z) * crate::poly(z, &EXP_TAIL_COEFFS);

    // exp(r) = (1 + r.high) + (r.low + tail) as a double-double.  `1 + r.high` is
    // exact (Fast2Sum, `|r.high| ≤ ln2/2N`); the low word then gathers the
    // reduction tail `r.low` in full and the polynomial tail.
    let head = fast_sum(1.0, r.high);
    let er = DoubleDouble {
        high: head.high,
        low: head.low + (r.low + tail),
    };

    // Fold in the table entry and normalize the mantissa into [1, 2), exactly as
    // the accurate path does.
    let (high, low) = EXP2_TABLE[j];
    let scaled = DoubleDouble { high, low } * er;
    let product = fast_sum(scaled.high, scaled.low);

    if product.high < 1.0 {
        (product * 2.0, q - 1)
    } else if product.high >= 2.0 {
        (product * 0.5, q + 1)
    } else {
        (product, q)
    }
}

/// Two-level fast leg for `eˣ`: `2`<sup>`q`</sup>` · 2`<sup>`j/4096`</sup>` · exp(dx)`.
///
/// Returns the mantissa as a double-double normalized into [1, 2) and the
/// adjusted `q`, like [`exp_mantissa_fast`], but reduces against a 4096-entry
/// (two 64-entry tables) grid so `|dx| ≤ ln2/8192` and a degree-3 plain-`f64`
/// tail suffices.  The table value `2`<sup>`j/4096`</sup>` = EXP2_T0[j>>6] ·
/// EXP2_T1[j&63]` (one `dd × dd`), folded in with CORE-MATH's lean
/// `fl = tl + (th·dx)·p` — no double-double `exp(r)` and no `dd × dd` poly
/// multiply.  `x` must be finite and within the non-overflow range.
#[inline]
pub(super) fn exp_two_level_fast(x: f64) -> (DoubleDouble, i64) {
    let (t, dx) = exp_two_level_reduce(x);
    exp_two_level_mantissa(t, dx)
}

/// Two-level base-`e` reduction: `(t, dx)` with `eˣ = 2^(t/4096)·exp(dx)`,
/// `t = round(4096·x/ln2)`, `|dx| ≤ ln2/8192`.
///
/// `scaled · LN2_OVER_4096_HI` is exact (HI has 24 trailing zero bits,
/// `|scaled| < 2²⁴`), so the FMA `x − scaled·HI` is exact; subtracting
/// `scaled · LO` finishes the residual.  `x` must be finite and in the
/// non-overflow range.
#[inline]
fn exp_two_level_reduce(x: f64) -> (i64, f64) {
    let scaled = (x * N_OVER_LN2_4096).round_ties_even();

    // SAFETY: `|x| < 746`, so `|scaled| < 2^23`.
    let t = unsafe { scaled.to_int_unchecked::<i64>() };

    let a = crate::fma(scaled, -LN2_OVER_4096_HI, x);
    let dx = crate::fma(scaled, -LN2_OVER_4096_LO, a);
    (t, dx)
}

/// Un-normalized lean two-level fold: returns `(th, fl, q)` with the value
/// `(th + fl)·2`<sup>`q`</sup>` = eˣ`, where `th = 2`<sup>`j/4096`</sup>` ∈ [1, 2)`,
/// `|fl| ≲ ln2/8192`, `q = t >> 12`, `j = t & 4095 = 64·i0 + i1`.
///
/// The table value `2`<sup>`j/4096`</sup>` = EXP2_T0[j>>6] · EXP2_T1[j&63]` (one
/// `dd × dd`), folded in with CORE-MATH's lean `fl = tl + (th·dx)·p` — no
/// double-double `exp(r)` and no `dd × dd` poly multiply.  Scalar [`exp`] gates
/// `th + fl` directly; [`exp_two_level_mantissa`] renormalizes it into [1, 2) for
/// the reuse consumers (`exp2`/`expm1`/`sinh`/`cosh`).
#[inline]
fn exp_two_level_fold(t: i64, dx: f64) -> (f64, f64, i64) {
    let i0 = ((t >> 6) & 63) as usize;
    let i1 = (t & 63) as usize;
    let q = t >> 12;

    let (t0h, t0l) = EXP2_T0[i0];
    let (t1h, t1l) = EXP2_T1[i1];
    let table = DoubleDouble {
        high: t0h,
        low: t0l,
    } * DoubleDouble {
        high: t1h,
        low: t1l,
    };

    // `exp(dx) − 1 = dx · p(dx)`; fold `th·(exp(dx) − 1)` into the table low word.
    // Dropping the `tl·(exp(dx) − 1) ≈ 2⁻⁶⁶` cross term keeps the leg under its
    // Ziv budget thanks to the finer table.
    let p = crate::poly(dx, &EXP_FAST3_COEFFS);
    let fl = crate::fma(table.high * dx, p, table.low);
    (table.high, fl, q)
}

/// Lean two-level fold for the reuse consumers: the [`exp_two_level_fold`] value
/// renormalized into the `(mantissa ∈ [1, 2), q)` contract of [`exp_mantissa_fast`].
#[inline]
fn exp_two_level_mantissa(t: i64, dx: f64) -> (DoubleDouble, i64) {
    let (th, fl, q) = exp_two_level_fold(t, dx);
    let product = fast_sum(th, fl);

    // `2^(j/4096) · exp(dx)` lies in (0.9999, 2.0001); fold its exponent into `q`.
    if product.high < 1.0 {
        (product * 2.0, q - 1)
    } else if product.high >= 2.0 {
        (product * 0.5, q + 1)
    } else {
        (product, q)
    }
}

/// Argument reduction for `2`<sup>`e`</sup> with a *double-double* exponent `e`.
///
/// Returns `(j, q, r)` with `2`<sup>`e`</sup>` = 2`<sup>`q`</sup>` · 2`<sup>`j/N`</sup>` · exp(r)`
/// and `|r| ≤ ln2/2N` — the base-2 counterpart of [`exp2`]'s reduction, lifted to a
/// double-double argument for [`pow`](super::pow), where `e = y·log₂x`.  The
/// caller must keep `|e.high|` inside the finite `2`<sup>`e`</sup> range
/// (`< ~1075`) so `round(N·e)` fits an `i64`.
#[inline]
pub(super) fn exp2_reduce_dd(e: DoubleDouble) -> (usize, i64, DoubleDouble) {
    let scaled = (e.high * EXP_N as f64).round_ties_even();

    // SAFETY: the caller keeps `e.high` within the finite 2^e range, so
    // `|scaled| < 2^18`.
    let m = unsafe { scaled.to_int_unchecked::<i64>() };
    let j = (m & (EXP_N - 1)) as usize;
    let q = m >> 7;

    // sigma = N·e − m.  `e.high·N` is exact (N is a power of two) and within ½ of
    // the integer `scaled`, so the high word is exact (Sterbenz); `e.low·N` is also
    // exact, and 2Sum normalizes the pair regardless of their relative size.
    let sigma = DoubleDouble::from_sum(
        crate::fma(e.high, EXP_N as f64, -scaled),
        e.low * EXP_N as f64,
    );

    // r = sigma · ln2/N as a double-double, `|r| ≤ ln2/2N`.
    let r = sigma
        * DoubleDouble {
            high: LN2_OVER_N_HI,
            low: LN2_OVER_N_LO,
        };
    (j, q, r)
}

/// Argument reduction for the exponential family.
///
/// Returns `(j, q, r)` with `x = (q·N + j)·ln2/N + r` and `|r| ≤ ln2/2N`.  The
/// caller must keep `|x|` small enough that `round(N·x/ln2)` fits an `i64`
/// (`|x| < ~746`, the finite exp range).
#[inline]
fn exp_reduce(x: f64) -> (usize, i64, DoubleDouble) {
    /// `N / ln(2)`, the scale that maps `x` to the reduction index
    const N_OVER_LN2: f64 = 184.664_965_233_787_3;

    let scaled = (x * N_OVER_LN2).round_ties_even();

    // SAFETY: `|x| < 746`, so `|scaled| < 2^18`.
    let n = unsafe { scaled.to_int_unchecked::<i64>() };
    let j = (n & (EXP_N - 1)) as usize;
    let q = n >> 7;

    // r as a double-double.  `scaled · LN2_OVER_N_HI` is exact because the high
    // word has 17 trailing zero bits, and the low word recovers the tail.
    let a = crate::fma(scaled, -LN2_OVER_N_HI, x);
    (j, q, DoubleDouble::from_sum(a, scaled * -LN2_OVER_N_LO))
}

/// Argument reduction for `eᵂ` with a *double-double* exponent `W`.
///
/// Returns `(j, q, r)` with `eᵂ = 2`<sup>`q`</sup>` · 2`<sup>`j/N`</sup>` · exp(r)`
/// and `|r| ≤ ln2/2N` — the base-`e` counterpart of [`exp_reduce`], lifted to a
/// double-double argument for `erfc`, where `W = Q(t) − x²`.  The caller must keep
/// `|W.high|` within the finite `eᵂ` range (`< ~746`) so `round(N·W/ln2)` fits an
/// `i64`.
#[inline]
pub(super) fn exp_reduce_dd(w: DoubleDouble) -> (usize, i64, DoubleDouble) {
    /// `N / ln(2)`, the scale that maps `W` to the reduction index
    const N_OVER_LN2: f64 = 184.664_965_233_787_3;

    let scaled = (w.high * N_OVER_LN2).round_ties_even();

    // SAFETY: the caller keeps `|W.high| < 746`, so `|scaled| < 2^18`.
    let n = unsafe { scaled.to_int_unchecked::<i64>() };
    let j = (n & (EXP_N - 1)) as usize;
    let q = n >> 7;

    // r = W − scaled·ln2/N as a double-double.  `scaled · LN2_OVER_N_HI` is exact
    // (the high word has 17 trailing zero bits), giving the high residual; the low
    // residual gathers `W.low` and the `LN2_OVER_N_LO` correction.
    let a = crate::fma(scaled, -LN2_OVER_N_HI, w.high);
    let b = crate::fma(scaled, -LN2_OVER_N_LO, w.low);
    (j, q, DoubleDouble::from_sum(a, b))
}

/// `eᵂ` as `2`<sup>`q`</sup>` · mantissa` (mantissa a double-double in [1, 2)) for
/// a double-double exponent `W`, the accurate counterpart of [`exp_dd_of_dd_fast`].
#[inline]
pub(super) fn exp_dd_of_dd(w: DoubleDouble) -> (DoubleDouble, i64) {
    let (j, q, r) = exp_reduce_dd(w);
    exp_mantissa(j, q, r)
}

/// Lean `eᵂ` for a double-double exponent `W` (≈2⁻⁶⁸ relative), the fast leg
/// `erfc` Ziv-gates against [`exp_dd_of_dd`].
#[inline]
pub(super) fn exp_dd_of_dd_fast(w: DoubleDouble) -> (DoubleDouble, i64) {
    let (j, q, r) = exp_reduce_dd(w);
    exp_mantissa_fast(j, q, r)
}

/// `eˣ` as `2`<sup>`q`</sup>` · mantissa` with the mantissa a double-double in [1, 2).
///
/// The caller must ensure `x` is finite and within the non-overflow range
/// (`|x| < ~710`); used by the hyperbolic functions, which need the extra words.
#[inline]
pub(super) fn exp_dd(x: f64) -> (DoubleDouble, i64) {
    let (j, q, r) = exp_reduce(x);
    exp_mantissa(j, q, r)
}

/// The exponential function
#[must_use]
#[inline]
pub fn exp(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }

    // Overflow / underflow thresholds, exact to the ulp: `exp` is finite at
    // x = 0x1.62e42fefa39efp+9 (→ f64::MAX) and overflows one ulp above, and is
    // the smallest subnormal at x = -0x1.74910d52d3051p+9, underflowing to +0 one
    // ulp below.  These FP compares (`comisd`, predicted not-taken) are cheaper
    // here than a `|x|`-bit magnitude trick, which would force an XMM→GPR `movq`.
    if x >= f64::from_bits(0x4086_2e42_fefa_39f0) {
        return f64::INFINITY;
    }
    if x <= f64::from_bits(0xc087_4910_d52d_3052) {
        return 0.0;
    }

    // Fast path: the un-normalized two-level fold `eˣ = (th + fl)·2^q`, gated
    // CORE-MATH style.  `th ∈ [1, 2)` and `|fl| ≲ ln2/8192`, so `ε = 2⁻⁶²` is
    // ~11 ulp of `fl` and survives the inner `fl ± ε`; the outer `th + …` then
    // resolves the nearest rounding without the renormalizing `fast_sum` + branch
    // the reuse contract needs.  `q ≥ −1021` keeps `(th + fl)·2^q ≥ 2⁻¹⁰²¹·⁰`
    // comfortably normal (so `fast_ldexp` is exact and the subnormal boundary
    // stays on the accurate path).
    let (t, dx) = exp_two_level_reduce(x);
    let (th, fl, q) = exp_two_level_fold(t, dx);
    if q >= -1021 {
        let lo = th + (fl - EXP_TWO_LEVEL_ZIV_EPS);
        let hi = th + (fl + EXP_TWO_LEVEL_ZIV_EPS);
        if lo == hi {
            return fast_ldexp(lo, q);
        }
    }

    exp_accurate(x)
}

/// Degree-7 double-double Horner of [`EXP_DD_COEFFS`]: `P(z) = (exp(z) − 1)/z`
/// for `z = dx` a double-double, `|dx| ≤ ln2/8192`.
///
/// Mirrors CORE-MATH's `opolydd` — each step multiplies the accumulator by `dx`
/// then folds in the next coefficient with a renormalizing Fast2Sum on the high
/// words, keeping the low word meaningful at ≈2⁻¹⁰⁷.
#[inline]
fn exp_poly_dd(dx: DoubleDouble) -> DoubleDouble {
    let (high, low) = EXP_DD_COEFFS[6];
    let mut acc = DoubleDouble { high, low };
    for &(c0, c1) in EXP_DD_COEFFS[..6].iter().rev() {
        acc = dx * acc;
        let s = fast_sum(c0, acc.high);
        acc = DoubleDouble {
            high: s.high,
            low: acc.low + (s.low + c1),
        };
    }
    acc
}

/// Correctly-rounded `eˣ` — [`exp`]'s rare fallback when the lean leg straddles a
/// rounding boundary.
///
/// Idiomatic port of CORE-MATH's `as_exp_accurate`: the same two-level grid as
/// the fast leg (`2`<sup>`j/4096`</sup>` = EXP2_T0[i0]·EXP2_T1[i1]`), but with the
/// reduced `dx` carried as a double-double (three-word `ln2/4096`, [`L2H`]/`L2L`/
/// `L2LL`) and `exp(dx)` evaluated by the degree-7 double-double [`exp_poly_dd`].
/// The double-double result reaches ≈2⁻¹⁰⁷, enough to correctly round every input
/// except a handful of sub-2⁻¹⁰⁷ near-ties, which [`exp_database`] resolves.  Kept
/// `#[cold]`/out-of-line so it does not bloat `exp`'s hot path.
#[cold]
#[inline(never)]
fn exp_accurate(x: f64) -> f64 {
    // |x| < 2⁻⁵⁴: eˣ = 1 + x to nearest (the reduction would underflow `t = 0`).
    if (x.to_bits() >> super::EXP_SHIFT) & 0x7ff < 0x3c9 {
        return 1.0 + x;
    }
    if let Some(r) = exp_database(x) {
        return r;
    }

    let tf = (x * N_OVER_LN2_4096).round_ties_even();
    // SAFETY: |x| < 746, so |tf| < 2²³.
    let jt = unsafe { tf.to_int_unchecked::<i64>() };

    // dx = x − t·ln2/4096 as a double-double.  `tf·L2H` is exact, so `x − tf·L2H`
    // is exact (Sterbenz); `L2L`, `L2LL` carry the rest.
    let dxh0 = crate::fma(tf, -L2H, x);
    let dxl = tf * L2L;
    let dxll = crate::fma(tf, L2LL, crate::fma(tf, L2L, -dxl));
    let dxh = dxh0 + dxl;
    let dx = DoubleDouble {
        high: dxh,
        low: (dxh0 - dxh) + dxl + dxll,
    };

    exp_two_level_finish(jt, dx)
}

/// Shared reconstruction tail of the two-level accurate paths ([`exp_accurate`]
/// and [`exp2_accurate`]): given the grid index `jt` (`i0 = (jt>>6)&63`,
/// `i1 = jt&63`, exponent `ie = jt>>12`) and the reduced argument `dx`
/// (`|dx| ≤ ln2/8192` as a double-double), evaluate
/// `2`<sup>`ie`</sup>` · 2`<sup>`j/4096`</sup>` · exp(dx)` correctly rounded
/// (subnormal-safe).
fn exp_two_level_finish(jt: i64, dx: DoubleDouble) -> f64 {
    let i0 = ((jt >> 6) & 63) as usize;
    let i1 = (jt & 63) as usize;
    let ie = jt >> 12;

    // exp(dx) = 1 + dx·P(dx); fold into the table value: 2^(j/4096)·exp(dx).
    let em1 = dx * exp_poly_dd(dx);
    let (t0h, t0l) = EXP2_T0[i0];
    let (t1h, t1l) = EXP2_T1[i1];
    let table = DoubleDouble {
        high: t0h,
        low: t0l,
    } * DoubleDouble {
        high: t1h,
        low: t1l,
    };

    let m = if table.high == 1.0 && table.low == 0.0 {
        // x near a multiple of ln2 (table = 1): the mantissa is `1 + (exp(dx) − 1)`,
        // a catastrophic near-1 sum.  Build it with an extra Fast2Sum so the low
        // word keeps the full residual, then round-to-odd nudge it off any exact
        // power-of-two tie (toward the discarded residual `e2`'s sign), so the
        // final `high + low` rounds correctly — CORE-MATH's `th == 1` branch.
        let s = fast_sum(1.0, em1.high);
        let pair = fast_sum(s.low, em1.low);
        let (mut fl, e2) = (pair.high, pair.low);
        if fl.to_bits() & (!0u64 >> 12) == 0 && e2 != 0.0 {
            let step = if (fl.to_bits() ^ e2.to_bits()) >> 63 == 1 {
                -1i64
            } else {
                1
            };
            fl = f64::from_bits(fl.to_bits().wrapping_add(step as u64));
        }
        DoubleDouble {
            high: s.high,
            low: fl,
        }
    } else {
        table.add_ordered(em1 * table)
    };

    // Normalize the mantissa into [1, 2) (folding its exponent into `ie`) for the
    // subnormal-safe final rounding.
    let (mantissa, ie) = if m.high < 1.0 {
        (m * 2.0, ie - 1)
    } else if m.high >= 2.0 {
        (m * 0.5, ie + 1)
    } else {
        (m, ie)
    };
    super::double::round_general64(mantissa, ie)
}

