/// 2 raised to the power `x`
#[must_use]
#[inline]
pub fn exp2(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }

    // `f64::MAX_EXP` and the threshold below which `exp2` rounds to zero
    if x >= 1024.0 {
        return f64::INFINITY;
    }
    if x <= -1075.0 {
        return 0.0;
    }

    // Fast path: the two-level lean mantissa.  Index `t = round(4096·x)`, residual
    // `dx = (4096·x − t)·ln2/4096`; `sigma = 4096·x − t` is exact (4096 is a power
    // of two).
    let scaled4 = (x * 4096.0).round_ties_even();
    // SAFETY: `|x| < 1075`, so `|scaled4| < 2^22`.
    let t = unsafe { scaled4.to_int_unchecked::<i64>() };
    let sigma4 = crate::fma(x, 4096.0, -scaled4);
    let dx = crate::fma(sigma4, LN2_OVER_4096_LO, sigma4 * LN2_OVER_4096_HI);
    let (product, qf) = exp_two_level_mantissa(t, dx);
    if qf >= -1021 {
        let lo = product.high + (product.low - EXP_TWO_LEVEL_ZIV_EPS);
        let hi = product.high + (product.low + EXP_TWO_LEVEL_ZIV_EPS);
        if lo == hi {
            return fast_ldexp(lo, qf);
        }
    }

    exp2_accurate(x)
}

/// 10 raised to the power `x`
#[must_use]
#[inline]
pub fn exp10(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }

    // Overflow threshold, exact to the ulp: `exp10` is finite at
    // x = 0x1.34413509f79fep+8 (→ ≈f64::MAX) and overflows at the next input up,
    // 0x1.34413509f79ffp+8.  Using the rounded decimal `308.2547155559…7` with
    // `>=` clipped the last finite input to ∞ (~1119 ulp early), so gate on the
    // exact first overflowing bit pattern instead.
    if x >= f64::from_bits(0x4073_4413_509f_79ff) {
        return f64::INFINITY;
    }
    if x <= -323.607_245_338_779_8 {
        return 0.0;
    }

    // 10^x = exp(x·ln10).  Two-level reduce the base-`e` exponent `w = x·ln10`:
    // `t = round(4096·x·log2(10))`, residual `dx = w − t·ln2/4096`, `|dx| ≤ ln2/8192`.
    // Unlike `exp`/`exp2`, `w` is not exact, so it is carried as a double-double to
    // form `dx`; the cheap two-level fold (degree-3 f64 tail, no dd × dd) then
    // replaces the N=128 `dd × dd` table-fold the old reduction routed through.
    let scaled = (x * N_LOG2_10_4096).round_ties_even();

    // SAFETY: `|x| < 324`, so `|scaled| < 2^22`.
    let t = unsafe { scaled.to_int_unchecked::<i64>() };

    // `w = x·ln10` as a double-double (`from_product` gives the exact `x·LN10_HI`
    // tail; `LN10_LO` finishes the low word).
    let w = DoubleDouble::from_product(x, LN10_HI);
    let wl = crate::fma(x, LN10_LO, w.low);

    // `dx = (w.high − scaled·HI) + (wl − scaled·LO)` as one f64.  `scaled·HI` is
    // exact (`HI` has 24 trailing zero bits, `|scaled| < 2²²`) and cancels against
    // `w.high` down to `|dx|` scale (Sterbenz), so the FMA is exact.
    let hi = crate::fma(-scaled, LN2_OVER_4096_HI, w.high);
    let dx = hi + crate::fma(-scaled, LN2_OVER_4096_LO, wl);

    // Fast path: the two-level lean fold, gated like `exp`.  `q ≥ −1021` keeps the
    // subnormal transition (where the mantissa's normalization can shift `q`) on the
    // accurate path.
    let (th, fl, q) = exp_two_level_fold(t, dx);
    if q >= -1021 {
        let lo = th + (fl - EXP_TWO_LEVEL_ZIV_EPS);
        let hi = th + (fl + EXP_TWO_LEVEL_ZIV_EPS);
        if lo == hi {
            return fast_ldexp(lo, q);
        }
    }

    exp10_accurate(x)
}

